package help;public class Guide {void main(){var input=new java.util.Scanner(System.in);var help=new java.util.LinkedHashMap<String,String>();help.put("условие","if (проверка) действие; else другоеДействие;");help.put("выбор","switch (значение) { case метка: действие; break; default: другоеДействие; }");help.put("счётчик","for (начало; проверка; шаг) действие;");help.put("проверка","while (проверка) действие;");help.put("после","do действие; while (проверка);");String selected;do{System.out.println(help.keySet());selected=input.next();if(!help.containsKey(selected))System.out.println("Выберите обозначение из списка.");}while(!help.containsKey(selected));System.out.print(help.get(selected));}}
